icash_next_before_sms_inbound_campaign:
CREATE OR REPLACE FUNCTION public.icash_next_before_sms_inbound_campaign()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prior jsonb;thread public.icash_text_threads;message uuid;ticket public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 prior:=public.icash_next_before_seller_openers();
 if prior->>'token' is not null then return prior;end if;
 if not exists(select 1 from public.icash_operating_budget where id=1 and enabled) then return prior;end if;
 if exists(select 1 from public.icash_automation_tickets where kind='seller_opener' and created_at>now()-interval '1 second') then return prior;end if;
 with candidates as materialized (
 select t.id,t.account_id from public.icash_text_threads t
 join public.icash_accounts a on a.id=t.account_id and not a.bot_paused
 join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents
 join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true'
 join public.icash_screening_jobs s on s.id=d.screening_id and s.account_id=t.account_id and s.state='complete' and s.result->'financialCheck'->>'status'='eligible' and s.completed_at>now()-interval '24 hours'
 join public.icash_timezone_names zone on zone.name=t.timezone
 where t.party='seller' and not t.paused and t.ai_mode='auto'
 and not exists(select 1 from public.icash_text_messages m where m.thread_id=t.id)
 and not exists(select 1 from public.icash_text_suppressions x where x.phone=t.recipient)
 and not exists(select 1 from public.icash_property_controls pc where pc.account_id=a.id and pc.property_id=s.snapshot->>'propertyId' and pc.manual)
 )
 select t.* into thread from candidates candidate join public.icash_text_threads t on t.id=candidate.id and t.account_id=candidate.account_id
 join public.icash_accounts a on a.id=t.account_id and not a.bot_paused
 join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents
 join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true'
 join public.icash_screening_jobs s on s.id=d.screening_id and s.account_id=t.account_id and s.state='complete' and s.result->'financialCheck'->>'status'='eligible' and s.completed_at>now()-interval '24 hours'
 join public.icash_timezone_names zone on zone.name=t.timezone
 where t.party='seller' and not t.paused and t.ai_mode='auto' and public.icash_sms_thread_dispatch_until(candidate.account_id,candidate.id)>now()
 and public.icash_sms_outreach_window_current(candidate.account_id,candidate.id)
 and not exists(select 1 from public.icash_text_messages m where m.thread_id=t.id)
 and not exists(select 1 from public.icash_text_suppressions x where x.phone=t.recipient)
 and not exists(select 1 from public.icash_property_controls pc where pc.account_id=a.id and pc.property_id=s.snapshot->>'propertyId' and pc.manual)
 order by t.id for update of t skip locked limit 1;
 if not found then return prior;end if;
 message:=public.icash_queue_seller_opener(thread.account_id,thread.id);
 if message is null then return prior;end if;
 insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(thread.account_id,'seller_opener',message) returning * into ticket;
 return jsonb_build_object('token',ticket.token);
end $function$

icash_next_before_unstarted_sms_recovery:
CREATE OR REPLACE FUNCTION public.icash_next_before_unstarted_sms_recovery()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m uuid;ticket public.icash_automation_tickets;
begin
 perform pg_advisory_xact_lock(726341927);
 if exists(select 1 from public.icash_operating_budget where id=1 and enabled) and not exists(select 1 from public.icash_automation_tickets where kind='seller_opener' and created_at>now()-interval '1 second') then
 with candidates as materialized (
 select th.id,th.account_id from public.icash_text_threads th join public.icash_accounts a on a.id=th.account_id and not a.bot_paused join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents join public.icash_deal_files d on d.id=th.deal_id and d.account_id=th.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true' join public.icash_screening_jobs sc on sc.id=d.screening_id and sc.account_id=d.account_id and sc.state='complete' and sc.result->'financialCheck'->>'status'='eligible' and sc.completed_at between now()-interval '24 hours' and now() join public.icash_timezone_names tz on tz.name=th.timezone
 where not exists(select 1 from public.icash_property_controls pc where pc.account_id=th.account_id and pc.property_id=sc.snapshot->>'propertyId' and pc.manual) and th.party='seller' and not th.paused and th.ai_mode='auto' and not exists(select 1 from public.icash_text_suppressions s where s.phone=th.recipient)
 and (not exists(select 1 from public.icash_text_messages where thread_id=th.id) or exists(select 1 from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=th.id and i.expires_at>now() and not exists(select 1 from public.icash_automation_tickets old where old.opener_message_id=msg.id)))
 )
 select th.* into t from candidates candidate join public.icash_text_threads th on th.id=candidate.id and th.account_id=candidate.account_id join public.icash_accounts a on a.id=th.account_id and not a.bot_paused join public.icash_wallets w on w.account_id=a.id and w.balance_cents>w.reserved_cents join public.icash_deal_files d on d.id=th.deal_id and d.account_id=th.account_id and d.stage='draft' and coalesce(d.terms->>'practice','false')<>'true' join public.icash_screening_jobs sc on sc.id=d.screening_id and sc.account_id=d.account_id and sc.state='complete' and sc.result->'financialCheck'->>'status'='eligible' and sc.completed_at between now()-interval '24 hours' and now() join public.icash_timezone_names tz on tz.name=th.timezone
 where public.icash_outreach_sms_current(candidate.account_id) and not exists(select 1 from public.icash_property_controls pc where pc.account_id=th.account_id and pc.property_id=sc.snapshot->>'propertyId' and pc.manual) and th.party='seller' and not th.paused and th.ai_mode='auto' and public.icash_sms_thread_dispatch_until(candidate.account_id,candidate.id)>now() and public.icash_sms_outreach_window_current(candidate.account_id,candidate.id) and not exists(select 1 from public.icash_text_suppressions s where s.phone=th.recipient)
 and (not exists(select 1 from public.icash_text_messages where thread_id=th.id) or exists(select 1 from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=th.id and i.expires_at>now() and not exists(select 1 from public.icash_automation_tickets old where old.opener_message_id=msg.id))) order by th.id for update of th skip locked limit 1;
 if found then
  select i.message_id into m from public.icash_sms_inbound_invitations i join public.icash_text_messages msg on msg.id=i.message_id and msg.state='ready' where i.thread_id=t.id and i.expires_at>now();
  if m is null then m:=public.icash_queue_seller_opener(t.account_id,t.id);end if;
  if m is not null then insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(t.account_id,'seller_opener',m) returning * into ticket;return jsonb_build_object('token',ticket.token);end if;
 end if;end if;
 return public.icash_next_before_sms_inbound_campaign();
end $function$

icash_queue_seller_opener:
CREATE OR REPLACE FUNCTION public.icash_queue_seller_opener(p_account uuid, p_thread uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;d public.icash_deal_files;principal text;buyer_description text;address text;seller text;greeting text:='Hi, ';message_body text;message uuid;choice jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
perform 1 from public.icash_operating_budget where id=1 for update;
 if not public.icash_outreach_sms_current(p_account) then return null;end if;
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account and party='seller' and not paused and ai_mode='auto' and public.icash_sms_thread_review_current(p_account,id,false) for update;
 if not found or exists(select 1 from public.icash_seller_opener_assignments where thread_id=t.id)
  or exists(select 1 from public.icash_text_messages where thread_id=t.id and (state in ('ready','dispatching','needs_review') or created_at>now()-interval '1 day')) then return null;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true';
 if not found then return null;end if;
 select trim(i.principal),case when nullif(trim(i.company_name),'') is null then 'an individual HomeOffer Network investor' else 'an independent HomeOffer Network cash buyer' end into principal,buyer_description from public.icash_customer_identities i where i.account_id=p_account;
 address:=public.icash_conversation_street(d.terms->>'address');
 if coalesce(length(address),0)=0 or coalesce(length(principal),0)=0 then return null;end if;
 -- A property-record owner is not necessarily the person replying. Use only
 -- a strict self-introduction from this same contact after an actually sent text.
 -- Capture the FIRST name, never disclose terms.seller or another recorded owner.
 select substring(m.body from '^(?:[Tt]his is|[Mm]y name is|I''m|I am) ([A-Z][a-z]{1,24})(?:[ ''-][A-Z][a-z]{1,24}){0,2}[.!]?$') into seller
 from public.icash_text_messages m
 where m.thread_id=t.id and m.account_id=p_account and m.direction='incoming' and m.state='received'
 and m.body ~ '^(?:[Tt]his is|[Mm]y name is|I''m|I am) ([A-Z][a-z]{1,24})(?:[ ''-][A-Z][a-z]{1,24}){0,2}[.!]?$'
 and exists(select 1 from public.icash_text_messages sent where sent.thread_id=t.id and sent.account_id=p_account and sent.direction='outgoing' and sent.state in ('accepted','delivered') and sent.provider_id is not null and sent.created_at<m.created_at)
 order by m.created_at desc,m.id desc limit 1;
 if lower(seller) in ('interested','owner','selling','ready','not','yes','no') then seller:=null;end if;
 if seller is not null then greeting:='Hi '||seller||', ';end if;
 if t.seller_intake_id is not null and public.icash_seller_contact_evidence(p_account,d.screening_id,t.seller_intake_id,t.recipient) is not null then
  select split_part(trim(l.name),' ',1) into seller from public.icash_seller_intakes l where l.id=t.seller_intake_id and l.phone=t.recipient;
  if seller is null or seller !~ '^[A-Za-z][A-Za-z]{0,30}$' then seller:=null;end if;
  message_body:=public.icash_seller_recipient_opener(p_account,t.id,seller,principal,address);
  if message_body is null then return null;end if;
 else
  message_body:='Is this '||case when seller is null then '' else seller||', ' end||'the owner of '||address||'? I am reaching out about a possible cash offer.';
 end if;
 -- Retain the existing one-segment rate. Never silently truncate identity/address or bill extra segments.
 if length(message_body)>160 or message_body ~ '[^A-Za-z0-9 .,!?]' then return null;end if;
 choice:=public.icash_assign_seller_opener(p_account,t.id);
 if choice is null then return null;end if;
 if choice->>'context'='interest-v2' then
  message_body:=replace(replace(choice->>'body','{owner}',case when seller is null then '' else seller||', ' end||'the owner'),'{address}',address);
  -- Any invalid expansion rolls back the new assignment along with this call.
  if length(message_body)>160 or message_body ~ '[^A-Za-z0-9 .,!?]' then raise exception 'Seller experiment copy requires review';end if;
 end if;
 update public.icash_seller_opener_assignments a set body=message_body where a.thread_id=t.id and a.account_id=p_account and a.message_id is null;
 message:=public.icash_queue_text(p_account,t.id,t.id,message_body,'{}');
 insert into public.icash_sms_seller_openings(thread_id,account_id,owner_question_id) values(t.id,p_account,message);
 return message;
end $function$
